#define _YY_GLSLES_ 1
varying vec4 v_vColour;
varying vec2 v_vTexcoord;

uniform sampler2D uMaskTexture;

uniform float uMaskBody;
uniform float uMaskHead;
uniform float uMaskHand;
uniform float uMaskWeapon;

float alphaThreshold(float alpha, float threshold) {

	return step(threshold, alpha);

}

float hasBit(float value, float bit) {
	
    return step(0.5, mod(floor(value / bit), 2.0));
	
}

void main() {
	
	vec4 colorRGBA = texture2D(gm_BaseTexture, v_vTexcoord);
	vec4 blendRGBA = v_vColour;
	
	vec4 maskRGBA = texture2D(uMaskTexture, v_vTexcoord);
	
	if(alphaThreshold(maskRGBA.a, 0.99) == 1.0) {
		
		maskRGBA = floor(maskRGBA * 255.0 + 0.5);
		
		float hasBody = hasBit(maskRGBA.r, 32.0);
		float hasHead = hasBit(maskRGBA.r, 64.0);
		
		float hasHand = hasBit(maskRGBA.g, 32.0);
		float hasWeapon = hasBit(maskRGBA.g, 64.0);
		
		float hasHandOrWeapon = max(hasHand, hasWeapon);
		float hasHandOrWeaponOrHead = max(hasHead, hasHandOrWeapon);

		float alphaMask = 0.0;
		
		alphaMask = max(alphaMask, hasBody * uMaskBody * (1.0 - hasHandOrWeaponOrHead));
		alphaMask = max(alphaMask, hasHead * uMaskHead * (1.0 - hasHandOrWeapon));
		alphaMask = max(alphaMask, hasHand * uMaskHand * (1.0 - hasWeapon));
		alphaMask = max(alphaMask, hasWeapon * uMaskWeapon);
		
		colorRGBA = colorRGBA * alphaThreshold(1.0 - alphaMask, 0.99);
		
	}

	gl_FragColor = colorRGBA * blendRGBA;
	
}

