varying vec2 v_vTexcoord;
varying vec4 v_vColour;

uniform float u_time;
uniform float u_pulseIntensity;

uniform vec2 u_texelSizeRatio;

void main() {
	
	vec2 v_texCoord = v_vTexcoord * u_texelSizeRatio;
	vec4 u_ghostColor = v_vColour;
	
	float u_distortionStrength = 0.01;
	float u_flickerIntensity = 0.3;
	float u_pulseSpeed = 10.0;
	//float u_pulseIntensity = 0.1;
	
    // --- 1. Wavy Distortion ---
    float distortionEffect = sin(u_time * 2.0 + v_texCoord.y * 15.0) * cos(u_time * 0.5 + v_texCoord.x * 10.0);
	
	vec2 distortedTexCoord = v_vTexcoord;
	distortedTexCoord.x += (distortionEffect * u_distortionStrength) / u_texelSizeRatio.x;
	distortedTexCoord.y += (sin(u_time * 1.5 + v_texCoord.x * 20.0) * u_distortionStrength * 0.5) / u_texelSizeRatio.y;
	
    // --- 2. Sample Texture ---
    // Sample the texture with the distorted coordinates
    vec4 originalColor = texture2D(gm_BaseTexture, distortedTexCoord);

    // If the original pixel is transparent, discard it to maintain sprite shape
    if (originalColor.a < 0.01) {
        discard;
    }

    // --- 3. Ghostly Color Tint ---
    vec3 tintedColor = 1.0 - ((1.0 - u_ghostColor.rgb) * (1.0 - originalColor.rgb));

