	vec2 uv = v_texcoord;
   
    vec3 p3 = vec3(uv, time*0.055);
	float value = simplex3d_fractal(p3*2.2);
	value = saturation + saturation * value - saturation;
    vec4 inNoise = vec4(vec3(value),.05);
    	
